#!/usr/bin/env node
/**
 * scripts/patch-capacitor-gradle.js
 *
 * Patches Capacitor library build.gradle files to use the AGP 8.13+ required
 * "=" assignment syntax (Gradle 8 deprecated space-assignment for DSL properties).
 *
 * Targeted files (all are in node_modules or generated by cap sync):
 *  - node_modules/@capacitor/android/capacitor/build.gradle
 *  - node_modules/@capacitor/filesystem/android/build.gradle
 *  - android/capacitor-cordova-android-plugins/build.gradle
 *
 * Run: node scripts/patch-capacitor-gradle.js
 */

const fs = require('fs');
const path = require('path');

/**
 * Apply a series of regex replacements to a file.
 * Each rule is [searchRegex, replacement].
 */
function patchFile(filePath, rules) {
  const abs = path.resolve(filePath);
  if (!fs.existsSync(abs)) {
    console.log(`  [skip] Not found: ${filePath}`);
    return;
  }

  let content = fs.readFileSync(abs, 'utf8');
  let changed = false;

  for (const [pattern, replacement] of rules) {
    const next = content.replace(pattern, replacement);
    if (next !== content) {
      changed = true;
      content = next;
    }
  }

  if (changed) {
    fs.writeFileSync(abs, content, 'utf8');
    console.log(`  [patched] ${filePath}`);
  } else {
    console.log(`  [clean]   ${filePath}`);
  }
}

// Rules that apply to all Capacitor plugin/library build.gradle files
const AGP8_RULES = [
  // minSdkVersion X  ->  minSdk = X
  [/\bminSdkVersion\s+/g, 'minSdk = '],
  // targetSdkVersion X  ->  targetSdk = X
  [/\btargetSdkVersion\s+/g, 'targetSdk = '],
  // versionCode N (bare integer, no = sign)  ->  versionCode = N
  [/\bversionCode\s+(\d)/g, 'versionCode = $1'],
  // versionName "x.y"  ->  versionName = "x.y"
  [/\bversionName\s+"([^"]+)"/g, 'versionName = "$1"'],
  // minifyEnabled false/true  ->  minifyEnabled = false/true
  [/\bminifyEnabled\s+(false|true)\b/g, 'minifyEnabled = $1'],
  // lintOptions { ... }  ->  lint { ... }  (deprecated block name)
  [/\blintOptions\s*\{/g, 'lint {'],
  // proguardFiles getDefaultProguardFile(...)  ->  proguardFiles(getDefaultProguardFile(...))
  // Only fix if not already wrapped in ()
  [/\bproguardFiles\s+getDefaultProguardFile\(/g, 'proguardFiles(getDefaultProguardFile('],
];

const FILES_TO_PATCH = [
  'node_modules/@capacitor/android/capacitor/build.gradle',
  'node_modules/@capacitor/filesystem/android/build.gradle',
  'android/capacitor-cordova-android-plugins/build.gradle',
];

console.log('[patch-capacitor-gradle] Starting...');
FILES_TO_PATCH.forEach((f) => patchFile(f, AGP8_RULES));
console.log('[patch-capacitor-gradle] Done.');
